/* Metade da telemetria do cruzamento entra por aqui.

   Desde que o cruzamento virou duas placas, a informacao chega partida: a placa
   1A (sinaleiras) publica fase, t_fase e pedidos em cidade/cruzamento/estado, e
   a 1B (sensores) publica carros, fluxo e vagas em cidade/cruzamento/sensores.

   Este no so guarda a leitura mais recente, com a hora. Quem junta e a
   coordenacao, que roda no ritmo da 1A - e o t_fase dela que manda na decisao.
   Guardar, em vez de casar as duas mensagens com um join, e de proposito: as
   duas placas publicam em ritmos independentes e uma pode sumir sem a outra.
   O carimbo de hora e o que deixa a coordenacao perceber que sumiu. */

const p = msg.payload;
if (!p) { return null; }

flow.set('cz_sensores', {
    carros: p.carros || [0, 0, 0, 0],
    fluxo:  p.fluxo  || [0, 0, 0, 0],
    livres: p.livres,
    t: Date.now()
});
return null;

/* Botoeira fisica -> pedido de travessia.

   O botao esta na placa 1B e a maquina de fases mora inteira na 1A; este no e a
   ponte entre as duas. A 1B publica so a BORDA da apertada ({"j":2}), nunca o
   estado do botao: ela nao tem como saber quando a travessia foi atendida -
   quem zera o pedido e a maquina de fases, do outro lado.

   Traduzido para o mesmo {"pedestre":j} da botoeira virtual do painel, que ja
   existia. Nenhum caminho novo foi inventado dentro da placa 1A.

   Se o Node-RED estiver fora do ar, o botao fisico nao chega na 1A - a
   travessia so sai pelo ciclo local. E o mesmo tipo de perda de eficiencia que
   a arquitetura ja aceita em toda entrada: nunca vira perda de seguranca. */

const p = msg.payload;
const j = (p && typeof p.j === 'number') ? p.j : null;
if (j === null || j < 0 || j > 3) { return null; }

node.status({ fill: 'blue', shape: 'dot', text: 'travessia ' + 'NSLO'[j] });
return { payload: JSON.stringify({ pedestre: j }) };

/* Quebra a telemetria do cruzamento nos widgets do painel. */
const s = msg.payload;
if (!s || !s.fase) { return null; }

const dir = ['N', 'S', 'L', 'O'];
const p = s.pedidos || [0, 0, 0, 0];

// carros vem da placa 1B, por outro topico (ver o no 'sensores do cruzamento')
const sens = flow.get('cz_sensores');
const cego = !sens || (Date.now() - sens.t) > 5000;
const c = cego ? [0, 0, 0, 0] : sens.carros;

const pedidas = dir.filter(function (d, i) { return p[i]; }).join('  ');
const modo = flow.get('cz_modo') || 'AUTO';
const sup  = s.supervisionado ? '' : '  (placa no ciclo local)';

return [
    { payload: s.fase },
    { payload: (modo === 'AUTO' ? 'Automatico' : 'Manual') + sup },
    { payload: cego ? 'sensores mudos' : (c[0] + c[1]) + ' carro(s)' },
    { payload: cego ? 'sensores mudos' : (c[2] + c[3]) + ' carro(s)' },
    { payload: pedidas || '-' }
];

/* Coordenacao adaptativa do cruzamento.
   Entra: cidade/cruzamento/estado (2 Hz) + cidade/cruzamento/sensores (2 Hz)
   Sai:   cidade/cruzamento/cmd

   A PLACA garante a seguranca (verde minimo, amarelo, entreverdes, tempo de
   travessia fixo). Aqui mora so a OTIMIZACAO: qual fase, e por quanto tempo.

   O parametro que domina as decisoes e o CUSTO DE TROCA: amarelo (2 s) mais
   entreverdes (1,5 s) sao 3,5 s em que ninguem anda. Trocar de fase para
   atender um unico carro costuma custar mais do que esperar. Por isso o verde
   nao termina no instante em que o detector limpa.

   Comando tem de sair pelo menos a cada 10 s, senao a placa conclui que perdeu
   o Node-RED e volta ao ciclo de tempo fixo dela. A decisao "ficar como esta"
   reenvia a fase atual como keepalive - a placa ignora comando igual a fase
   corrente, entao nao ha efeito colateral. */

const s = msg.payload;
if (!s || !s.fase) { return null; }

const GAP         = 2500;    // ausencia continua que encerra o verde (folga)
const VERDE_MAX   = 15000;   // teto de justica
const PED_ESPERA  = 12000;   // acima disso o pedestre tem prioridade absoluta
const KEEPALIVE   = 4000;
const SENSOR_MUDO = 5000;    // sem leitura nova ha mais que isso: sensores mudos

const st = flow.get('cz_st') || {};
const agora = Date.now();

/* De onde vem cada metade da informacao.
   fase, t_fase e pedidos chegam nesta mensagem, da placa 1A. carros e fluxo vem
   da placa 1B por outro topico e ficam no contexto, com a hora da leitura. */
const sens  = flow.get('cz_sensores');
const cego  = !sens || (agora - sens.t) > SENSOR_MUDO;
const carros = cego ? [0, 0, 0, 0] : sens.carros;
const fluxo  = cego ? [0, 0, 0, 0] : sens.fluxo;
const pedidos = s.pedidos || [0, 0, 0, 0];

const modo   = flow.get('cz_modo') || 'AUTO';
const manual = flow.get('cz_fase_manual') || 'VIA_A';

/* SENSORES MUDOS: para de comandar, de proposito.
   Nao ha o que otimizar sem saber quem esta esperando, e insistir seria pior do
   que calar: com carros[] zerado a regra "ninguem esperando" retem o verde, e o
   cruzamento congelaria numa fase so ate aparecer pedido de pedestre. Calando,
   em 10 s (T_SEM_COMANDO) a placa 1A conclui que perdeu o supervisor e reassume
   o ciclo de tempo fixo dela - que alterna as vias e continua atendendo pedido
   de pedestre, sem depender da rede. E a degradacao projetada: perde-se
   eficiencia, nunca seguranca.
   O modo MANUAL escapa: ali quem decide e o operador (ou o modo atrator), e
   nenhum dos dois depende do detector. */
if (cego && modo !== 'MANUAL') {
    node.status({ fill: 'yellow', shape: 'ring', text: 'sensores mudos - ciclo local' });
    flow.set('cz_st', st);
    return null;
}
node.status({});

const temA = carros[0] + carros[1] > 0;          // Norte + Sul
const temB = carros[2] + carros[3] > 0;          // Leste + Oeste
const temPedestre = pedidos.some(function (p) { return p; });

// --- desde quando ha pedestre esperando ---
if (temPedestre) { if (!st.pedDesde) { st.pedDesde = agora; } }
else             { st.pedDesde = null; }

if (st.fase !== s.fase) {
    st.fase = s.fase;
    st.semCarro = null;
}

/* Taxa de chegada por via, com esquecimento exponencial.
   Medida CONTINUAMENTE, entre mensagens consecutivas - e nao dentro da fase
   corrente. Medir por fase nao funcionaria justamente onde esta taxa e usada:
   durante a travessia todos os carros estao parados e o fluxo da fase e zero
   nas duas vias. Com meia-vida de ~1 min, isto responde a pergunta certa:
   qual via anda mais movimentada ultimamente. */
const ant = st.fluxoAnt;
if (ant) {
    let dA = (fluxo[0] - ant[0]) + (fluxo[1] - ant[1]);
    let dB = (fluxo[2] - ant[2]) + (fluxo[3] - ant[3]);
    if (dA < 0 || dB < 0) { dA = 0; dB = 0; }      // contador zerou (placa reiniciou)
    st.taxaA = (st.taxaA || 0) * 0.995 + dA;
    st.taxaB = (st.taxaB || 0) * 0.995 + dB;
}
st.fluxoAnt = fluxo.slice();
const taxaA = st.taxaA || 0;
const taxaB = st.taxaB || 0;

let alvo = null;

if (modo === 'MANUAL') {
    alvo = manual;                               // operador assumiu: so reafirma

} else if (s.fase === 'VIA_A' || s.fase === 'VIA_B') {
    const souA   = (s.fase === 'VIA_A');
    const minha  = souA ? temA : temB;
    const outra  = souA ? temB : temA;
    const oposta = souA ? 'VIA_B' : 'VIA_A';

    // relogio de folga: so conta ausencia CONTINUA no meu proprio detector
    if (minha) { st.semCarro = null; }
    else if (!st.semCarro) { st.semCarro = agora; }

    const folgaVencida = st.semCarro && (agora - st.semCarro) >= GAP;
    const tetoVencido  = s.t_fase >= VERDE_MAX;
    const pedUrgente   = st.pedDesde && (agora - st.pedDesde) >= PED_ESPERA;

    if (pedUrgente) {
        alvo = 'PEDESTRES';                      // esperou demais: passa na frente
    } else if (!outra && !temPedestre) {
        alvo = s.fase;                           // ninguem esperando: retem o verde
    } else if (tetoVencido || folgaVencida) {
        // fim natural da fase: agora sim atende quem estava esperando
        alvo = temPedestre ? 'PEDESTRES' : oposta;
    } else {
        alvo = s.fase;                           // ainda descarregando: estende
    }

} else if (s.fase === 'PEDESTRES') {
    // prepara a via mais movimentada; se as taxas estao proximas, desempata por
    // quem tem carro parado agora
    if (Math.abs(taxaA - taxaB) > 0.5) { alvo = (taxaA > taxaB) ? 'VIA_A' : 'VIA_B'; }
    else if (temA !== temB) { alvo = temA ? 'VIA_A' : 'VIA_B'; }
    else { alvo = 'VIA_A'; }

} else {
    alvo = s.destino;                            // em transicao: mantem a supervisao
}

flow.set('cz_st', st);

if (!alvo || alvo === 'AMARELO' || alvo === 'ENTREVERDES') { return null; }

const ultimo = flow.get('cz_ultimo_envio') || 0;
const antes  = flow.get('cz_ultimo_alvo');
if (alvo !== antes || (agora - ultimo) >= KEEPALIVE) {
    flow.set('cz_ultimo_alvo', alvo);
    flow.set('cz_ultimo_envio', agora);
    return { payload: JSON.stringify({ fase: alvo }) };
}
return null;

/* Botoes de modo. AUTO devolve a decisao ao coordenador; qualquer outro
   fixa a fase ate que AUTO seja apertado de novo. */
const b = msg.payload;
if (b === 'AUTO') {
    flow.set('cz_modo', 'AUTO');
    return { payload: JSON.stringify({ fase: 'NORMAL' }) };   // sai do piscante
}
flow.set('cz_modo', 'MANUAL');
flow.set('cz_fase_manual', b);
flow.set('cz_ultimo_alvo', null);              // forca reenvio imediato
return { payload: JSON.stringify({ fase: b }) };

/* Consolida o estado das placas a partir do LWT e do heartbeat.

   O LWT diz se a placa esta conectada ao broker, mas nao se ela esta viva: uma
   placa travada com a conexao aberta continuaria "online". Por isso o
   heartbeat tambem entra na conta - sem batida ha mais de 30 s, a placa e
   dada como muda, mesmo que o broker ainda a considere conectada.

   O nome da placa sai do proprio topico (cidade/<placa>/status). Por isso a
   placa das sinaleiras aparece como 'cruzamento' - ela herdou os topicos do
   cruzamento inteiro - e a de entradas, que nasceu depois, como 'sensores'.

   MODULO NOVO APARECE SOZINHO. As cinco placas do projeto sao listadas sempre,
   mesmo antes de darem sinal de vida: uma placa que nunca conectou tem de
   aparecer OFFLINE, nao sumir. Qualquer outra que publique em
   cidade/<nome>/status entra na lista sem editar esta funcao, e se o heartbeat
   dela trouxer o campo "nome", e ele que aparece. Ate 2026-09 a lista era
   fechada nas cinco: o 'mqtt in' ja assinava cidade/+/status, mas um modulo
   novo ficava invisivel aqui - o que desmentia, no painel, a modularidade
   que o projeto afirma. */

const t = msg.topic.split('/');
const placa = t[t.length - 2];
const tipo  = t[t.length - 1];

const st = flow.get('estado_placas') || {};

// O tick de 10 s so reavalia quem ficou mudo. Nao e placa, e nao entra na lista.
if (placa !== 'tick') {
    st[placa] = st[placa] || {};
    if (tipo === 'status') {
        st[placa].conectada = String(msg.payload).trim() === 'online';
    } else if (tipo === 'heartbeat') {
        st[placa].ultimoHb = Date.now();
        const p = msg.payload || {};
        st[placa].uptime = p.uptime;
        st[placa].rssi   = p.rssi;
        if (typeof p.nome === 'string' && p.nome.trim()) st[placa].nome = p.nome.trim();
    }
    flow.set('estado_placas', st);
}

const NOMES = { cruzamento: 'Sinaleiras', sensores: 'Sensores',
                iluminacao: 'Iluminação', ambiental: 'Ambiental',
                seguranca: 'Segurança' };
const placas = Object.keys(NOMES).concat(Object.keys(st).filter(function (k) {
    return !(k in NOMES) && k !== 'tick';
}));
const agora = Date.now();
const linhas = [];
let vivas = 0;

placas.forEach(function (k) {
    const e = st[k] || {};
    const nome = NOMES[k] || e.nome || (k.charAt(0).toUpperCase() + k.slice(1));
    const mudo = !e.ultimoHb || (agora - e.ultimoHb) > 30000;
    let sit;
    if (!e.conectada)      { sit = 'OFFLINE'; }
    else if (mudo)         { sit = 'sem heartbeat'; }
    else                   { sit = 'ok · ' + (e.rssi !== undefined ? e.rssi + ' dBm' : '') ; vivas++; }
    linhas.push(nome + ': ' + sit);
});

return [
    { payload: linhas.join('   |   ') },
    { payload: vivas + ' de ' + placas.length + ' placas respondendo' }
];

flow.set('atrator', msg.payload === true);
if (!msg.payload) { flow.set('cz_modo', 'AUTO'); }
return null;

/* MODO ATRATOR - a maquete nunca parada.

   Cuidado nao obvio: a coordenacao adaptativa RETEM o verde quando nao ha
   demanda nenhuma, que e o comportamento correto para transito real e
   exatamente o errado para uma vitrine. Sem carrinho no detector, o cruzamento
   ficaria estatico. Por isso o atrator assume o controle manual do cruzamento
   e alterna as fases por conta propria.

   Nao mexe na enchente nem no detector de gas: as duas tem sirene, e um evento
   de quatro horas com sirene disparando sozinha e insuportavel. */

if (!flow.get('atrator')) {
    if (flow.get('cz_modo') === 'MANUAL') { flow.set('cz_modo', 'AUTO'); }
    return null;
}

const p = (flow.get('atrator_passo') || 0) + 1;
flow.set('atrator_passo', p);

// o coordenador reafirma a fase manual a cada ciclo, entao basta trocar o alvo
const CICLO = ['VIA_A', 'VIA_A', 'PEDESTRES', 'VIA_B', 'VIA_B', 'PEDESTRES'];
flow.set('cz_modo', 'MANUAL');
flow.set('cz_fase_manual', CICLO[p % CICLO.length]);
flow.set('cz_ultimo_alvo', null);           // forca reenvio imediato

const alvo = CICLO[p % CICLO.length];
const saidas = [null, null];
const msgs = [];

/* Publica a fase DIRETO, em vez de so ajustar o contexto e deixar o
   coordenador emitir. O coordenador so roda quando chega telemetria da placa;
   se a placa estiver muda, o atrator ficaria parado justamente no momento em
   que ele existe para evitar isso. Como o modo manual ja foi fixado acima, o
   coordenador apenas reafirma a mesma fase - nao ha disputa. */
if (alvo === 'PEDESTRES') {
    // botoeira antes da fase, senao a placa recusa a travessia sem pedido
    msgs.push({ payload: JSON.stringify({ pedestre: p % 4 }) });
}
msgs.push({ payload: JSON.stringify({ fase: alvo }) });
saidas[0] = msgs;

// pulso no poste a cada ~30 s: simula alguem passando
if (p % 4 === 0) {
    saidas[1] = { payload: JSON.stringify({ modo: 'ON' }) };
} else if (p % 4 === 1) {
    saidas[1] = { payload: JSON.stringify({ modo: 'AUTO' }) };
}
return saidas;
